const P = require('lv-automation').pulse;
const r = $json; if (!r.lead_id) return { json: { action: 'none' } };
const c = { lead: { id: r.lead_id, first_name: r.first_name, language: r.language, opted_out_at: r.opted_out_at, conv_state: r.conv_state || {} }, outcome: { outcome: r.outcome, marked_at: r.marked_at, lead_reach_check: r.lead_reach_check }, booking: { id: r.booking_id }, reach: { sent_at: r.reach_sent_at, answered_at: r.reach_answered_at }, broker: { contact_person: r.contact_person }, suppressed: r.suppressed, already_sent: false, last_inbound_at: r.last_inbound_at, outbound_count: Number(r.outbound_count || 0) };
const d = P.pulseDue(c, Date.now());
return { json: { ...d, lead_id: r.lead_id, booking_id: r.booking_id, cycle_id: r.cycle_id, brand_id: r.brand_id, broker_id: r.broker_id, phone: r.phone, version: P.VERSION } };

const d = $('Decide (pulse.pulseDue)').item.json;
let wa; let content;
if (d.channel === 'template') {
  const comps = [{ type: 'body', parameters: d.vars.map((t) => ({ type: 'text', text: String(t) })) }];
  d.buttons.forEach(([p], i) => comps.push({ type: 'button', sub_type: 'quick_reply', index: String(i), parameters: [{ type: 'payload', payload: p }] }));
  wa = { messaging_product: 'whatsapp', to: d.phone, type: 'template', template: { name: d.template, language: { code: 'en' }, components: comps } };
  content = 'template lead_pulse';
} else {
  // inside the 24-h window: the same approved words as a session interactive message (no template fee)
  wa = { messaging_product: 'whatsapp', to: d.phone, type: 'interactive', interactive: { type: 'button', body: { text: d.body }, action: { buttons: d.buttons.map(([id, title]) => ({ type: 'reply', reply: { id, title } })) } } };
  content = d.body;
}
return { json: { ...d, wa, content, step: 'ask', idem: d.idempotency_key } };

