const P = require('lv-automation').pulse;
const j = $json; const lead = j.lead || {}; const msg = j.msg || {}; const now = Date.now();
const c = { lead, booking: { id: (lead.conv_state && lead.conv_state.pulse_booking_id) || null } };
const key = String(msg.payload || '').split(':')[0];
let r; let kind;
if (key === 'pulse_yes' || key === 'pulse_no') { r = P.onPulseTap(msg.payload, c, now); kind = 'tap'; }
else if (P.isPulseLine(msg.text, lead.conv_state || {}, now)) { r = P.onPulseLine(msg.text, c); r.booking_id = c.booking.id; kind = 'line'; }
else return { json: { skip: true, reason: 'not a pulse answer (W07 handles it)' } };
if (r.error || !r.booking_id) return { json: { skip: true, reason: r.error || 'no booking for this pulse' } };
const lang = lead.language === 'af' ? 'af' : 'en';
return { json: { skip: false, kind, r, lang, lead_id: lead.id, brand_id: lead.brand_id, broker_id: lead.broker_id, cycle_id: lead.cycle_id || null, phone: msg.from, wamid: msg.wamid, version: P.VERSION } };

